Update the generated controller to include the required endpoints.
Example:
```ts
import {
  Body,
  Controller,
  Get,
  Patch,
  Post,
  Put,
  Delete
} from "@nestjs/common"

@Controller()
export class AppController {
  @Get()
  getHello() {
    return {
      method: "GET",
      message: "Hello from GET",
    }
  }

  @Post()
  create(@Body() body: Record<string, unknown>) {
    return {
      method: "POST",
      message: "Hello from POST",
      body,
    }
  }

  @Put()
  update(@Body() body: Record<string, unknown>) {
    return {
      method: "PUT",
      message: "Hello from PUT",
      body,
    }
  }

  @Patch()
  patch(@Body() body: Record<string, unknown>) {
    return {
      method: "PATCH",
      message: "Hello from PATCH",
      body,
    }
  }

  @Delete()
  remove() {
    return {
      method: "DELETE",
      message: "Hello from DELETE",
    }
  }
}
```

